&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;translation-28&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Bachelor&#39;s degree or above, more than 7 years of Java or Go backend development experience, more than 3 years of architecture design experience.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;29&quot; data-index=&quot;2.&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;translation-30&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Proficient in Java (Spring Boot, etc.) or Go (go-zero, etc.) microservice ecosystems, practitioners of both ecosystems preferred&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;31&quot; data-index=&quot;3.&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;translation-32&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Have experience in designing and tuning high-concurrency systems, and have experience in developing and architecting large-scale distributed systems.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;33&quot; data-index=&quot;4.&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;translation-34&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Familiar with microservice structure, with practical experience in containerization and ByteMesh such as K8s and Docker.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;35&quot; data-index=&quot;5.&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;translation-36&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Experience in architecture design and stability assurance in extreme peak scenarios such as high traffic and market trends.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;37&quot; data-index=&quot;6.&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;translation-38&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Possess online problem location and troubleshooting capabilities, with a sound stability management strategy.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ol&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;39&quot;&gt;&amp;nbsp;&lt;/div&gt;
