&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;42&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;43&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Bilingual: fluent in English and Mandarin Chinese.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
