&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-8&quot;&gt;&lt;strong&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-8-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Reliability &amp;amp; &lt;/span&gt;&lt;span class=&quot;text-only text-with-abbreviation text-with-abbreviation-bottomline&quot;&gt;Security&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;ul class=&quot;richTextDocs-unOrderList richTextDocs-unOrderList-disc&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9&quot;&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9-0&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9-0-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Establish an SLO/&lt;/span&gt;&lt;span class=&quot;text-only text-with-abbreviation text-with-abbreviation-bottomline&quot;&gt;SLA&lt;/span&gt;&lt;span class=&quot;text-only&quot;&gt; framework and champion a Blameless Postmortem culture&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9-1&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9-1-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Shift security left (DevSecOps) by embedding security scanning and compliance checks directly into the delivery pipeline&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9-2&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-9-2-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Architect multi-cloud/hybrid cloud strategies, making informed trade-offs between cost, elasticity, and stability&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-10&quot;&gt;&lt;strong&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-10-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Team Building&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;ul class=&quot;richTextDocs-unOrderList richTextDocs-unOrderList-disc&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-11&quot;&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-11-0&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-11-0-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Recruit, develop, and motivate the DevOps/SRE team, establishing clear technical career growth paths&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-11-1&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-11-1-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Make sound technical trade-off decisions under resource constraints, and clearly communicate the business value of technical investments to non-technical stakeholders&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-12&quot;&gt;&lt;strong&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-12-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Requirements&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;div class=&quot;rich-text-paragraph&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-13&quot;&gt;&lt;strong&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-13-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Must-Have&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;/div&gt;
&lt;ul class=&quot;richTextDocs-unOrderList richTextDocs-unOrderList-disc&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14&quot;&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-0&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-0-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;10+ years of engineering experience in the internet/tech industry, with 5+ years of hands-on DevOps/SRE/platform engineering experience&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-1&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-1-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Proven experience building high-concurrency, high-availability production systems (10M+ daily requests or equivalent complexity); experience in e-commerce, fintech, gaming, or healthcare is preferred&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-2&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-2-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Experience leading a DevOps/SRE team of 30+; bonus for candidates who have built a team from scratch or significantly elevated team effectiveness&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-3&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-3-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Proficiency in container orchestration (Docker, Kubernetes) with production-grade cluster planning, capacity management, and incident handling experience&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
&lt;li class=&quot;richTextDocs-listItem&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-4&quot;&gt;
&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;efb0aa0f-5cd0-4d74-b540-04e4bff2da97-14-4-0&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Hands-on experience with mainstream CI/CD tools (Jenkins, GitLab CI, ArgoCD, etc.) and IaC tools (Terraform, Helm, Ansible, etc.)&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
&lt;/li&gt;
