&lt;div class=&quot;richTextDocs-listItem__text&quot;&gt;&lt;span class=&quot;text-only&quot; data-eleid=&quot;45&quot;&gt;&lt;span class=&quot;text-only&quot;&gt;Diploma in Finance, Business, or a related discipline.&lt;/span&gt;&lt;/span&gt;&lt;/div&gt;
